  await click('p3LinkProjectFile');await page.wait_for_function("document.getElementById('p3SaveStatus').textContent.startsWith('File connected')");await page.evaluate('__p3QA.add()');await click('p3SaveProject');await saved();await page.wait_for_function("document.getElementById('p3SaveStatus').textContent.includes('and to')")
  data=await page.evaluate("async()=>{const root=await navigator.storage.getDirectory(),f=await root.getFileHandle('SaveTest.p3sculpt');return JSON.parse(await (await f.getFile()).text())}");assert len(data['meshes'])==4;print('PASS connected file overwritten by Save Now')
